import{_ as t,o,c as a,a5 as i}from"./chunks/framework.BfQ7H7Qx.js";const p=JSON.parse('{"title":"FR 3.10.5 — Update User Violation Status","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/09-admin-functions/3-10-5-update-user-violation-status/spec.md","filePath":"feature/srs/09-admin-functions/3-10-5-update-user-violation-status/spec.md"}'),n={name:"feature/srs/09-admin-functions/3-10-5-update-user-violation-status/spec.md"};function s(d,e,r,c,l,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-10-5-—-update-user-violation-status" tabindex="-1">FR 3.10.5 — Update User Violation Status <a class="header-anchor" href="#fr-3-10-5-—-update-user-violation-status" aria-label="Permalink to &quot;FR 3.10.5 — Update User Violation Status&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.10.5</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-132</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Update User Violation Status</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Admin Functions (<code>3.10</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Admin</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-30, BR-34</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01, MSG02, MSG03, MSG07</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified (Verified against <code>AdminController</code> (<code>/violations</code> &amp; <code>/sanction</code>), <code>user_strikes</code>, and <code>sanction_reviews</code>)</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Enable system <code>Admin</code> to inspect a user&#39;s violation history (<code>GET /api/v1/admin/users/{userId}/violations</code>), issue or revoke community-guideline strikes (<code>POST /api/v1/admin/users/{userId}/violations</code>), and adjudicate account sanctions (<code>POST /api/v1/admin/users/{userId}/sanction</code> — warning, temporary restriction, suspension, or unflag) with full auditability (<code>BR-34</code>).</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized <code>Admin</code>, I want to execute <strong>Update User Violation Status</strong> with strong ACID financial/administrative guarantees, deterministic concurrency protection, and complete audit logging so that BrandHub&#39;s operations strictly satisfy <code>BR-30, BR-34</code> without manual database intervention.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Canonical Role &amp; Tenant Security:</strong> Server-side authorization enforces <code>Admin</code> on every request (<code>Admin</code> verified against live DB <code>user_system_roles</code>; <code>Owner</code>/<code>Manager</code>/<code>Creator</code> verified against live <code>agencies</code> / <code>workspace_members</code>). Unauthorized callers receive <code>403 FORBIDDEN</code> (<code>MSG07</code>) or scoped <code>404 NOT_FOUND</code> on IDOR probes.</li><li><strong>Core Domain &amp; Financial Invariants:</strong></li></ol><ul><li><strong>1. Self-Sanction &amp; Fellow-Admin Guard (<code>BR-34</code>):</strong> An <code>Admin</code> cannot sanction their own account or arbitrarily strip another <code>Admin</code> without super-guard checks.</li><li><strong>2. Progressive Strike Ledger &amp; Token Invalidation:</strong> Strikes persist in <code>user_strikes</code> and <code>sanction_reviews</code>; escalating to <code>SUSPENDED</code> atomically updates <code>users.status</code>, revokes active <code>user_refresh_tokens</code>, and records <code>admin_account_operations</code> + notification.</li></ul><ol start="3"><li><strong>Auditability &amp; Idempotency:</strong> Every mutation records correlation <code>requestId</code> and structured audit evidence (<code>audit_logs</code> / <code>billing_audit_events</code> / <code>admin_account_operations</code>), and supports safe retry without duplicate financial side effects.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> All headings, table columns, status pills, dialogs, validation hints, and error banners use key-parallel translations (<code>admin.strikes.{history,issueStrike,sanction,reasons}</code> in <code>src/i18n/locales/{vi,en}/admin.json</code>) on <code>brandhub-web</code> and <code>tr()</code> on <code>brandhub-mobile-app</code> — zero hardcoded Vietnamese or English text in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All components (<code>pages/admin/components/AdminStrikeDialog.tsx</code>, <code>AdminAccountsPanel.tsx</code>, <code>AdminUserTable.tsx</code> on Web and <code>src/screens/admin/AdminUserStrikesScreen.tsx</code>, <code>AdminUsersScreen.tsx</code> on Mobile) use semantic CSS variables / Tailwind <code>dark:</code> variants and <code>useAppPreferences().palette</code> tokens with WCAG AA contrast across Light and Dark modes.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/admin/components/AdminStrikeDialog.tsx</code>, <code>AdminAccountsPanel.tsx</code>, <code>AdminUserTable.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/admin/AdminUserStrikesScreen.tsx</code>, <code>AdminUsersScreen.tsx</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Busy:</strong> Skeleton placeholders on initial query; disabled submit button + spinner during in-flight mutation to prevent double-submit races.</li><li><strong>Empty:</strong> Contextual localized empty state (e.g. zero invoices/moderation items/users matching filter) with zero fabricated mock data.</li><li><strong>Success:</strong> Scoped <code>TanStack Query</code> cache invalidation, updated KPI/row state, and localized confirmation toast.</li><li><strong>Conflict / Error:</strong> Explicit <code>409</code> stale-revision reload prompt or localized validation banner preserving user draft inputs.</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method &amp; Endpoint</th><th style="text-align:left;">Auth / Guard</th><th style="text-align:left;">Controller &amp; Service Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/admin/users/{userId}/violations?page={1}&amp;size={20}</code></td><td style="text-align:left;">Bearer (<code>Admin</code>)</td><td style="text-align:left;"><code>AdminController.history()</code> -&gt; returns <code>AdminStrikeSummary</code> &amp; paginated <code>user_strikes</code> + <code>sanction_reviews</code></td></tr><tr><td style="text-align:left;"><code>POST /api/v1/admin/users/{userId}/violations</code></td><td style="text-align:left;">Bearer (<code>Admin</code>)</td><td style="text-align:left;"><code>AdminController</code> -&gt; records a documented violation strike (<code>AdminStrikeRequest</code>) with reason &amp; evidence reference</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/admin/users/{userId}/sanction</code></td><td style="text-align:left;">Bearer (<code>Admin</code>)</td><td style="text-align:left;"><code>AdminController</code> -&gt; applies or lifts sanction (<code>AdminSanctionRequest</code>), revoking refresh tokens if suspended</td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>FORBIDDEN</code> (<code>403</code>, <code>MSG07</code>): Caller lacks <code>Admin</code> permission or attempts cross-Agency/cross-Workspace access.</li><li><code>CONFLICT</code> (<code>409</code>, <code>MSG03</code>): Stale <code>expectedRevision</code> / <code>rowVersion</code>, duplicate idempotency key with mutated payload, or prohibited self-sanction/last-Admin demotion.</li><li><code>BAD_REQUEST</code> / <code>PAYLOAD_TOO_LARGE</code> (<code>400</code> / <code>413</code>, <code>MSG02</code> / <code>MSG14</code>): Invalid date range, negative/unsafe integer amount, malformed CSV, or de-scoped operation (e.g., plan downgrade or non-SePay provider).</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Related SRS FRs &amp; Modules:</strong> <a href="./../3-10-4-content-moderation-queue/spec.html">FR 3.10.4 — Content Moderation Queue</a> · <a href="./../3-10-9-deactivate-user/spec.html">FR 3.10.9 — Deactivate User</a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/09-admin-functions.html">BA Specification</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Verified via JUnit 5 + isolated PostgreSQL/MongoDB integration tests, TypeScript/Playwright Web checks, Jest Mobile tests, <code>vi.json</code>/<code>en.json</code> key parity, and Light/Dark theme audit (<a href="./test.html">test.md</a>).</li><li><strong>Out of Scope:</strong> De-scoped capabilities (subscription plan downgrade, PayOS/VNPay/Stripe gateways, or copyright/plagiarism moderation).</li></ul>',21)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
